import { Suspense } from "react";
import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import Reveal from "@/components/Reveal";
import { projects } from "@/data/site";

export function generateStaticParams() {
  return projects.map((p) => ({ slug: p.slug }));
}

export async function generateMetadata(
  props: PageProps<"/projects/[slug]">,
): Promise<Metadata> {
  const { slug } = await props.params;
  const project = projects.find((p) => p.slug === slug);
  return project ? { title: project.title, description: project.summary } : {};
}

// 读取 params 的部分放在 <Suspense> 里，这样页面跳转能立即显示外壳（Next 16 的 instant navigation 要求）
export default function ProjectPage(props: PageProps<"/projects/[slug]">) {
  return (
    <Suspense fallback={<div className="min-h-screen" />}>
      <ProjectContent params={props.params} />
    </Suspense>
  );
}

async function ProjectContent({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const index = projects.findIndex((p) => p.slug === slug);
  if (index === -1) notFound();

  const project = projects[index];
  const next = projects[(index + 1) % projects.length];

  return (
    <article className="mx-auto max-w-4xl px-6 pb-24 pt-32">
      <Reveal>
        <Link href="/#work" className="text-sm text-muted hover:text-foreground">
          ← 返回作品
        </Link>
        <p className="mt-8 font-mono text-sm text-muted">
          {project.year} · {project.tags.join(" / ")}
        </p>
        <h1 className="mt-3 text-4xl font-bold tracking-tight sm:text-6xl">{project.title}</h1>
        <p className="mt-4 text-xl text-muted">{project.summary}</p>
      </Reveal>

      <Reveal delay={0.1}>
        <div className={`mt-12 aspect-video rounded-2xl bg-gradient-to-br ${project.gradient}`} />
      </Reveal>

      <div className="mt-12 space-y-6 text-lg leading-relaxed">
        {project.body.map((para, i) => (
          <Reveal key={i}>
            <p>{para}</p>
          </Reveal>
        ))}
      </div>

      {project.link && (
        <a
          href={project.link}
          target="_blank"
          rel="noreferrer"
          className="mt-10 inline-block rounded-full bg-foreground px-6 py-3 text-background"
        >
          访问项目 ↗
        </a>
      )}

      <Link
        href={`/projects/${next.slug}`}
        className="group mt-24 block border-t border-border pt-10"
      >
        <p className="text-sm text-muted">下一个作品</p>
        <p className="mt-2 text-3xl font-bold transition-transform group-hover:translate-x-2">
          {next.title} →
        </p>
      </Link>
    </article>
  );
}
